@BeforeEach
void emptyStorage() {
    storage.reset();
}

// Same pattern as PUT, so a malformed path gets 404 here rather than 405 from the PUT handler.
@ParameterizedTest
@ValueSource(strings = {"/logs/0004f2abcdef-app.log", "/logs/not-a-log-file-name", "/logs", "/logs/", "/logs/a/b"})
void headIsAlwaysNotFound(String path) throws Exception {
    mockMvc.perform(head(path))
            .andExpect(handler().methodName("head"))
            .andExpect(status().isNotFound());
}

// One row per status code in openapi.yaml, with every row's body still unread afterwards.
@ParameterizedTest
@CsvSource(delimiter = '|', nullValues = "none", value = {
        "/logs/not-a-log-file-name                | valid   | log line  | 400",
        "/logs/0004f2abcdef-phone.cfg             | valid   | log line  | 400",
        "/logs/extra/0004f2abcdef-app.log         | valid   | log line  | 400",
        "/logs/                                   | valid   | log line  | 400",
        "/logs                                    | valid   | log line  | 400",
        "/logs/0004f2abcdef-calls.xml             | valid   | log line  | 403",
        "/logs/0004f2abcdef-app.log               | missing | log line  | 403",
        "/logs/0004f2000000-app.log               | valid   | log line  | 403",
        "/logs/0004f2abcdef-app.log               | valid   | none      | 411",
        "/logs/0004f2abcdef-app.log               | valid   | log line! | 413" })
void rejectsOnHeadersWithoutReadingTheBody(String path, String headers, String body, int expected)
        throws Exception {
    MvcResult result = mockMvc.perform(upload(path, headers, body))
            .andExpect(handler().methodName("put"))
            .andExpect(status().is(expected))
            .andReturn();

    assertBodyUnread(result, body);
    assertThat(storage.files()).isEmpty();
}

@Test
void storesTheBodyAndAnswers200() throws Exception {
    mockMvc.perform(upload("/logs/0004f2abcdef-app.log", "valid", "log line"))
            .andExpect(handler().methodName("put"))
            .andExpect(status().isOk());

    assertThat(storage.files().values()).singleElement().satisfies(file -> {
        assertThat(file.object().key().format()).isEqualTo(KEY);
        assertThat(new String(file.body(), StandardCharsets.UTF_8)).isEqualTo("log line");
    });
}

// One row per storage rejection in openapi.yaml. The fixed clock gives every upload the same key, so the stored
// file makes the next upload collide with it.
@ParameterizedTest
@CsvSource(delimiter = '|', value = { "stored  | 429", "failing | 429" })
void storageProblemsAre429(String storageState, int expected) throws Exception {
    if (storageState.equals("stored")) {
        mockMvc.perform(upload("/logs/0004f2abcdef-app.log", "valid", "first")).andExpect(status().isOk());
    } else {
        storage.failWith(new LogStorageException(KEY, new IllegalStateException("S3 down")));
    }

    mockMvc.perform(upload("/logs/0004f2abcdef-app.log", "valid", "log line"))
            .andExpect(handler().methodName("put"))
            .andExpect(status().is(expected));

    assertThat(storage.files().values()).allSatisfy(
            file -> assertThat(new String(file.body(), StandardCharsets.UTF_8)).isEqualTo("first"));
}

// When Tomcat's read of the body fails it answers 400, or 408 on a timeout, by itself, so the service has to log
// and return the same code rather than 429. MockMvc's request can't fail a read, so a spy of it does.
@ParameterizedTest
@CsvSource(delimiter = '|', value = { "reset   | 400 | BODY_INCOMPLETE", "timeout | 408 | BODY_TIMEOUT" })
void aBodyThatStopsArrivingGetsTheCodeTomcatSent(String failure, int expected, String reason,
                                                 CapturedOutput output) throws Exception {
    IOException cause = failure.equals("timeout") ? new SocketTimeoutException("Read timed out")
            : new IOException("Connection reset");

    mockMvc.perform(upload("/logs/0004f2abcdef-app.log", "valid", "log line").with(failingBody(cause)))
            .andExpect(handler().methodName("put"))
            .andExpect(status().is(expected));

    assertThat(storage.files()).isEmpty();
    assertThat(output.getAll()).contains("upload mac=0004f2abcdef type=app.log key=" + KEY + " size=8 status="
            + expected + " reason=" + reason);
}

@Test
void eachUploadLogsOneLineWithoutTheBody(CapturedOutput output) throws Exception {
    mockMvc.perform(upload("/logs/0004f2abcdef-app.log", "valid", "secret!")).andExpect(status().isOk());
    mockMvc.perform(upload("/logs/0004f2abcdef-app.log", "valid", "secret!"))
            .andExpect(status().isTooManyRequests());
    mockMvc.perform(upload("/logs/not-a-log-file-name", "valid", "secret!"))
            .andExpect(status().isBadRequest());
